morse.watch('[aria-label="Tools"]', tools => {
  if (tools.querySelector('[aria-label="Save as PNG"]')) return;
  const btn = morse.el('button', {
    'aria-label': 'Save as PNG',
    title: 'Save as PNG',
    text: '💾',
    on: { click: () => {
      const canvas = morse.$('#board');
      if (!canvas) return;
      const a = morse.el('a', { href: canvas.toDataURL('image/png'), download: 'sketch.png' });
      document.body.appendChild(a);
      a.click();
      a.remove();
      morse.toast('Saved sketch.png');
    }}
  });
  tools.appendChild(btn);
});

morse.watch(".top", bar => {
  if (bar.querySelector("[data-morse-save]")) return;
  const btn = morse.el("button", {
    type: "button",
    "data-morse-save": "",
    "aria-label": "Save as PNG",
    text: "Save PNG",
    style: "margin-left:auto;margin-right:12px;padding:6px 12px;font:inherit;font-size:13px;color:inherit;background:transparent;border:1px solid currentColor;border-radius:6px;cursor:pointer;align-self:center",
    on: {
      click: () => {
        const board = document.querySelector("#board");
        if (!board) return;
        board.toBlob(blob => {
          if (!blob) return;
          const url = URL.createObjectURL(blob);
          const a = document.createElement("a");
          a.href = url;
          a.download = "sketch.png";
          document.body.appendChild(a);
          a.click();
          a.remove();
          setTimeout(() => URL.revokeObjectURL(url), 1000);
        }, "image/png");
      }
    }
  });
  bar.appendChild(btn);
});

