morse.watch("#__next > div:nth-of-type(2) > main > div:nth-of-type(1)", bar => {
  if (bar.querySelector("[data-sort-price]")) return;
  const btn = morse.el("button", {
    text: "Sort by price: low to high",
    "data-sort-price": "",
    style: "margin-left:auto;font:inherit;font-size:14px;color:inherit;background:none;border:1px solid currentColor;border-radius:6px;padding:4px 10px;cursor:pointer;opacity:.8",
    on: { click: () => {
      const grid = morse.$("#__next > div:nth-of-type(2) > main > div:nth-of-type(2) > div");
      if (!grid) return;
      const price = card => {
        const m = (card.textContent || "").match(/\$([\d,]+(?:\.\d+)?)/);
        return m ? parseFloat(m[1].replace(/,/g, "")) : Infinity;
      };
      const cards = Array.from(grid.children).sort((a, b) => price(a) - price(b));
      cards.forEach(c => grid.appendChild(c));
    } }
  });
  bar.appendChild(btn);
});

const SORT_BTN = "[data-morse-sort]";

const priceOf = card => {
  const leaf = [...card.querySelectorAll("*")]
    .find(e => e.children.length === 0 && /^\$\d/.test(e.textContent.trim()));
  return leaf ? parseFloat(leaf.textContent.replace(/[^0-9.]/g, "")) : Infinity;
};

function sortByPrice() {
  const grid = morse.$("#__next > div:nth-of-type(2) > main > div:nth-of-type(2) > div");
  if (!grid) return;
  [...grid.children]
    .sort((a, b) => priceOf(a) - priceOf(b))
    .forEach(card => grid.appendChild(card));
  morse.toast("Sorted by price, lowest first");
}

morse.watch("#__next > div:nth-of-type(2) > main > div:nth-of-type(1)", row => {
  if (row.querySelector(SORT_BTN)) return;
  row.appendChild(morse.el("button", {
    text: "Sort: price low to high",
    "data-morse-sort": "",
    style: "margin-left:auto;font:inherit;font-size:14px;color:inherit;background:none;border:1px solid currentColor;border-radius:6px;padding:4px 10px;cursor:pointer;opacity:.8",
    on: { click: sortByPrice }
  }));
});

const toolbar = "#__next > div:nth-of-type(2) > main > div:nth-of-type(1)";
const grid = "#__next > div:nth-of-type(2) > main > div:nth-of-type(2)";

const priceOf = card => {
  const m = card.textContent.match(/\$(\d+(?:\.\d+)?)/);
  return m ? parseFloat(m[1]) : 1e9;
};

morse.watch(toolbar, bar => {
  const btn = morse.el("button", {
    text: "Sort by price ↑",
    style: "margin-left:auto;font:inherit;font-size:14px;color:inherit;background:transparent;border:1px solid currentColor;border-radius:6px;padding:4px 10px;cursor:pointer;",
    on: {
      click: () => {
        const g = morse.$(grid)[0];
        if (!g) return;
        const cards = Array.from(g.children);
        cards.sort((a, b) => priceOf(a) - priceOf(b));
        g.append(...cards);
      }
    }
  });
  bar.append(btn);
});

