results.js:
morse.watch("#where", h => {
  if (h.nextElementSibling?.classList.contains("all-off")) return;
  const btn = morse.el("button", {
    class: "all-off",
    type: "button",
    text: "All devices off",
    "aria-label": "Turn all devices off",
    on: {
      click: () => {
        let n = 0;
        morse.$$("device-card").forEach(card => {
          card.shadowRoot?.querySelectorAll("button[aria-label]").forEach(b => {
            if (!b.disabled && /: on$/.test(b.getAttribute("aria-label"))) {
              b.click();
              n++;
            }
          });
        });
        morse.toast(n ? `Turned off ${n} device${n === 1 ? "" : "s"}` : "Everything is already off");
      }
    }
  });
  h.after(btn);
});

